BEGIN;
CREATE TABLE IF NOT EXISTS governed_bidders(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,user_id INTEGER NOT NULL,verification_state TEXT NOT NULL DEFAULT 'pending' CHECK(verification_state IN('pending','verified','rejected','expired')),verification_reference TEXT,verified_by INTEGER,verified_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS governed_lots(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,catalog_reference TEXT NOT NULL,title TEXT NOT NULL,provenance JSONB NOT NULL DEFAULT '{}',reserve_cents BIGINT NOT NULL CHECK(reserve_cents>=0),min_increment_cents BIGINT NOT NULL CHECK(min_increment_cents>0),current_bid_cents BIGINT NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'catalogued' CHECK(state IN('catalogued','verified','open','closed','settled','disputed')),opens_at TIMESTAMPTZ,closes_at TIMESTAMPTZ,created_by INTEGER NOT NULL,closed_by INTEGER,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,catalog_reference),CHECK(closes_at IS NULL OR opens_at IS NULL OR closes_at>opens_at));
CREATE TABLE IF NOT EXISTS governed_bids(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,lot_id BIGINT NOT NULL REFERENCES governed_lots(id) ON DELETE RESTRICT,bidder_id BIGINT NOT NULL REFERENCES governed_bidders(id) ON DELETE RESTRICT,amount_cents BIGINT NOT NULL CHECK(amount_cents>0),sequence INTEGER NOT NULL,idempotency_key TEXT NOT NULL,previous_hash TEXT NOT NULL,entry_hash TEXT NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,lot_id,sequence),UNIQUE(tenant_id,lot_id,idempotency_key),UNIQUE(entry_hash));
CREATE TABLE IF NOT EXISTS governed_auction_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,lot_id BIGINT REFERENCES governed_lots(id) ON DELETE RESTRICT,actor_id INTEGER NOT NULL,action TEXT NOT NULL,from_state TEXT,to_state TEXT,rationale TEXT,evidence JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS auction_provider_outbox(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL CHECK(provider IN('payments_escrow','identity_kyc','shipping','tax','notifications','provenance')),lot_id BIGINT REFERENCES governed_lots(id) ON DELETE RESTRICT,operation TEXT NOT NULL,payload_reference TEXT NOT NULL,idempotency_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','delivering','delivered','failed','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,provider,idempotency_key));
CREATE OR REPLACE FUNCTION reject_bid_mutation()RETURNS trigger AS $$BEGIN RAISE EXCEPTION 'governed bid/event ledgers are append-only';END;$$LANGUAGE plpgsql;DROP TRIGGER IF EXISTS bid_ledger_append_only ON governed_bids;CREATE TRIGGER bid_ledger_append_only BEFORE UPDATE OR DELETE ON governed_bids FOR EACH ROW EXECUTE FUNCTION reject_bid_mutation();DROP TRIGGER IF EXISTS auction_events_append_only ON governed_auction_events;CREATE TRIGGER auction_events_append_only BEFORE UPDATE OR DELETE ON governed_auction_events FOR EACH ROW EXECUTE FUNCTION reject_bid_mutation();
COMMIT;
